#!/usr/bin/env node
/**
 * Test File Analyzer - Identifies which tests are boilerplate vs real
 * and focuses on files that NEED implementation
 * 
 * Usage: node scripts/test-analyzer.js
 */

const fs = require('fs');
const path = require('path');

const TEST_DIRS = [
  path.join(__dirname, '../tests/unit/services'),
  path.join(__dirname, '../tests/unit/routes'),
  path.join(__dirname, '../tests/unit/workers')
];

/**
 * Check if test file has real test cases (not just boilerplate)
 */
function isBoilerplateTest(content) {
  // Count actual test assertions
  const testCalls = (content.match(/test\(['"]/g) || []).length;
  const todoMarks = (content.match(/\/\/ TODO:/g) || []).length;
  const realAssertions = (content.match(/expect\(.+\)\.to[A-Z]/g) || []).length;
  
  // If more TODOs than real assertions, it's boilerplate
  return todoMarks > realAssertions * 0.5 && testCalls < 10;
}

/**
 * Categorize test file
 */
function categorizeTest(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  const name = path.basename(filePath);
  
  const testCount = (content.match(/test\(['"]/g) || []).length;
  const todoCount = (content.match(/\/\/ TODO:/g) || []).length;
  const hasRealAssertions = /expect\(.+\)\.toEqual\(|expect\(.+\)\.toBe\([^)]*\$|expect\(.+\)\.toContain/m.test(content);
  
  return {
    name,
    testCount,
    todoCount,
    isBoilerplate: isBoilerplateTest(content),
    hasRealAssertions,
    size: content.length
  };
}

/**
 * Main execution
 */
function main() {
  console.log('📊 Test File Analyzer\n');
  
  const results = {
    boilerplate: [],
    partial: [],
    complete: [],
    total: 0
  };

  TEST_DIRS.forEach(dir => {
    if (!fs.existsSync(dir)) return;
    
    const files = fs.readdirSync(dir)
      .filter(f => f.endsWith('.spec.js'))
      .map(f => path.join(dir, f));

    files.forEach(file => {
      const analysis = categorizeTest(file);
      results.total++;

      if (analysis.isBoilerplate) {
        results.boilerplate.push(analysis);
      } else if (analysis.todoCount > 0) {
        results.partial.push(analysis);
      } else {
        results.complete.push(analysis);
      }
    });
  });

  console.log(`📦 Total test files: ${results.total}\n`);
  
  console.log(`🟥 BOILERPLATE (need implementation): ${results.boilerplate.length}`);
  results.boilerplate.forEach(t => {
    console.log(`   - ${t.name.padEnd(40)} (${t.testCount} tests, ${t.todoCount} TODOs)`);
  });

  console.log(`\n🟨 PARTIAL (some tests, needs expansion): ${results.partial.length}`);
  results.partial.forEach(t => {
    console.log(`   - ${t.name.padEnd(40)} (${t.testCount} tests, ${t.todoCount} TODOs)`);
  });

  console.log(`\n🟩 COMPLETE (real test cases): ${results.complete.length}`);
  results.complete.forEach(t => {
    console.log(`   - ${t.name.padEnd(40)} (${t.testCount} tests)`);
  });

  console.log(`\n📈 Coverage Impact (rough estimate):`);
  console.log(`   Lines of boilerplate: ${results.boilerplate.reduce((s, t) => s + t.size, 0)}`);
  console.log(`   Expected coverage gain from implementation: +3-5%`);
  
  console.log(`\n📋 Priority Implementation Order:`);
  console.log(`   1. Fix boilerplate tests (${results.boilerplate.length} files)`);
  console.log(`   2. Expand partial tests (${results.partial.length} files)`);
  console.log(`   3. Add edge cases to complete tests`);
}

if (require.main === module) {
  main();
}

module.exports = { categorizeTest, isBoilerplateTest };
